import {expect} from '@playwright/test';
import {loginAs} from 'whippet/login';
export async function loginShop({page}) {
  await page.goto('http://host.docker.internal:19387/login');
  await loginAs(page, '7da20730-874d-41ff-aea0-7a5650f37c12', 'input[name=username]', 'input[name=password]', 'button[type=submit]');
  await expect(page).toHaveURL('http://host.docker.internal:19387/products');
  await expect(page.getByTestId('account-state')).toHaveText('Authenticated synthetic customer');
  return {authenticated:true};
}

module.harness:
import {test,expect} from '@playwright/test';
import {loginShop} from '@lib/shop-login';
test('shop login with platform role',async({page})=>{
 const result=await test.step('Stage 1: platform role login',()=>loginShop({page}));
 await test.step('Stage 2: protected page assertions',async()=>{
  await expect(page).toHaveURL('http://host.docker.internal:19387/products');
  await expect(page.getByTestId('account-state')).toHaveText('Authenticated synthetic customer');
  expect(result).toEqual({authenticated:true});
 });
});

